import{_ as a,c as t,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1784988047000}'),r={name:"guide/installation.md"};function n(l,e,s,p,h,d){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Minesweeper is available as a universal app on the App Store, supporting iPhone, iPad, and Mac with a single purchase.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><ul><li><strong>App Store</strong>: <a href="https://apps.apple.com/app/id6793471840" target="_blank" rel="noreferrer">Download Minesweeper</a> — universal app for iPhone, iPad &amp; Mac</li></ul><h3 id="app-store-recommended" tabindex="-1">App Store (Recommended) <a class="header-anchor" href="#app-store-recommended" aria-label="Permalink to &quot;App Store (Recommended)&quot;">​</a></h3><p>The App Store version provides automatic updates and seamless integration across all your Apple devices.</p><ul><li><strong>App Store ID</strong>: 6793471840</li><li><strong>Link</strong>: <a href="https://apps.apple.com/app/id6793471840" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793471840</a></li><li><strong>Platforms</strong>: iPhone, iPad, Mac (universal app)</li><li><strong>Price</strong>: Check the App Store listing for current pricing</li></ul><h2 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to &quot;iPhone / iPad&quot;">​</a></h3><ol><li>Open the <strong>App Store</strong> on your device</li><li>Search for &quot;Minesweeper&quot; or use the direct link above</li><li>Tap <strong>Get</strong> or <strong>Buy</strong> to download</li><li>The app will install automatically</li><li>Launch Minesweeper from your Home Screen</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to &quot;Mac&quot;">​</a></h3><ol><li>Open the <strong>App Store</strong> on your Mac</li><li>Search for &quot;Minesweeper&quot; or use the direct link above</li><li>Click <strong>Get</strong> or <strong>Buy</strong> to purchase</li><li>The app will automatically download and install</li><li>Launch Minesweeper from your Applications folder or Launchpad</li></ol><h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h2><p>When you launch Minesweeper for the first time, no special permissions are required. The game is fully offline — no network access, no data collection, no ads. Just start playing.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Updates are handled automatically by the App Store. To check for updates manually, open the App Store and go to your <strong>Account → Updates</strong> section.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to &quot;iPhone / iPad&quot;">​</a></h3><ol><li>Press and hold the Minesweeper app icon</li><li>Tap <strong>Remove App</strong> → <strong>Delete App</strong></li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to &quot;Mac&quot;">​</a></h3><ol><li>Quit Minesweeper</li><li>Drag <code>Minesweeper.app</code> from <code>Applications</code> to the Trash</li><li>(Optional) Remove app data:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.minesweeper</span></span></code></pre></div><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 15.0 or later</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) or later</li><li><strong>CPU</strong>: Apple Silicon (M-series) or Intel (64-bit)</li><li><strong>Memory</strong>: 2GB minimum</li><li><strong>Storage</strong>: ~50 MB</li><li><strong>Network</strong>: Not required</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If you encounter issues during installation:</p><ul><li><strong>macOS blocks the app</strong>: Open <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong> for Minesweeper</li><li><strong>App not appearing</strong>: Restart the App Store app or your device and try again</li></ul><p>For more help, visit the <a href="./troubleshooting.html">Troubleshooting guide</a> or open an issue on the project repository.</p>',28)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
